CREATE OR REPLACE FUNCTION public.iniciar_atendimento(_empresa_id uuid,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF NOT (public.tem_papel_plataforma(auth.uid(),'suporte') OR public.tem_papel_plataforma(auth.uid(),'admin_master')) THEN RAISE EXCEPTION 'Acesso restrito à plataforma'; END IF; IF length(trim(_motivo))<5 OR length(_motivo)>1000 THEN RAISE EXCEPTION 'Informe a finalidade do atendimento'; END IF; IF NOT EXISTS(SELECT 1 FROM public.empresas WHERE id=_empresa_id) THEN RAISE EXCEPTION 'Empresa não encontrada'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF EXISTS(SELECT 1 FROM public.suporte_atendimentos WHERE usuario_id=auth.uid() AND encerrado_em IS NULL) THEN RAISE EXCEPTION 'Encerre o atendimento atual'; END IF; INSERT INTO public.suporte_atendimentos(usuario_id,empresa_id,motivo) VALUES(auth.uid(),_empresa_id,trim(_motivo)) RETURNING id INTO v_id; INSERT INTO public.logs_auditoria(empresa_id,ator_id,ator_contexto,acao,recurso_tipo,recurso_id,resultado,detalhes) VALUES(_empresa_id,auth.uid(),CASE WHEN public.tem_papel_plataforma(auth.uid(),'admin_master') THEN 'admin_master' ELSE 'suporte' END,'atendimento_iniciado','atendimento',v_id,'sucesso',jsonb_build_object('motivo',trim(_motivo))); RETURN v_id; END; $$;
CREATE OR REPLACE FUNCTION public.encerrar_atendimento(_atendimento_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_empresa uuid; BEGIN IF NOT (public.tem_papel_plataforma(auth.uid(),'suporte') OR public.tem_papel_plataforma(auth.uid(),'admin_master')) THEN RAISE EXCEPTION 'Acesso restrito à plataforma'; END IF; UPDATE public.suporte_atendimentos SET encerrado_em=now() WHERE id=_atendimento_id AND usuario_id=auth.uid() AND encerrado_em IS NULL RETURNING empresa_id INTO v_empresa; IF v_empresa IS NULL THEN RAISE EXCEPTION 'Atendimento não encontrado'; END IF; INSERT INTO public.logs_auditoria(empresa_id,ator_id,ator_contexto,acao,recurso_tipo,recurso_id,resultado,detalhes) VALUES(v_empresa,auth.uid(),CASE WHEN public.tem_papel_plataforma(auth.uid(),'admin_master') THEN 'admin_master' ELSE 'suporte' END,'atendimento_encerrado','atendimento',_atendimento_id,'sucesso','{}'); END; $$;